import{_ as r,o as t,c as o,a5 as a}from"./chunks/framework.CXroN2RO.js";const c="/study/images/browser/service-worker-lifecycle.svg",i="/study/images/browser/service-worker-fetch.svg",k=JSON.parse('{"title":"Service Workerとオフライン動作 — 登録、制御、応答の選択","description":"","frontmatter":{"title":"Service Workerとオフライン動作 — 登録、制御、応答の選択","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"Service Workerの登録、install、waiting、activate、ページの制御を説明する。fetchイベントでの応答、Cache APIを使うオフライン動作、更新と登録解除の範囲を整理する。","aliases":["Service Worker","ServiceWorker","オフライン","offline","scope","register","install","waitUntil","waiting","activate","ready","controller","controllerchange","fetch event","respondWith","skipWaiting","clients.claim","unregister","precache","offline fallback"],"verification":"一次資料照合（2026-11-05）"}},"headers":[],"relativePath":"browser/service-worker-offline.md","filePath":"browser/service-worker-offline.md"}'),s={name:"browser/service-worker-offline.md"};function l(d,e,n,h,f,p){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="service-workerとオフライン動作-—-登録、制御、応答の選択" tabindex="-1">Service Workerとオフライン動作 — 登録、制御、応答の選択 <a class="header-anchor" href="#service-workerとオフライン動作-—-登録、制御、応答の選択" aria-label="Permalink to &quot;Service Workerとオフライン動作 — 登録、制御、応答の選択&quot;">​</a></h1><p><strong>Service Worker</strong>は、ブラウザが登録してイベントに応じて動かすワーカーです。担当するページの取得処理に関わり、要求に対して通常の取得結果、Cache APIから読んだ応答、自分で作った応答などを返せます。通信できない状況で画面やデータを提供できるかは、担当範囲、事前に保存した資源、要求ごとの応答方針で決まります。<a href="https://w3c.github.io/ServiceWorker/#control-and-use" target="_blank" rel="noreferrer">Service Workersの制御モデル</a></p><p>CPU計算をページから分担するDedicated Workerは、ページが作成してメッセージをやり取りします。Service Workerでは登録と実行中の環境が別の寿命を持ち、処理するイベントがなくなるとブラウザが実行環境を終了できます。後でイベントが来れば再び起動され、グローバル変数は作り直されます。イベントをまたいで残すデータには、用途に応じてCache APIやIndexedDBを使います。<a href="https://w3c.github.io/ServiceWorker/#service-worker-lifetime" target="_blank" rel="noreferrer">Service Workersの実行寿命</a>、<a href="/study/browser/web-workers-messages.html">Web Workerとメッセージ通信</a>、<a href="/study/browser/storage-lifetime.html">ブラウザの保存領域</a></p><h2 id="登録するurlと、ページを担当するscope" tabindex="-1">登録するURLと、ページを担当するscope <a class="header-anchor" href="#登録するurlと、ページを担当するscope" aria-label="Permalink to &quot;登録するURLと、ページを担当するscope&quot;">​</a></h2><p>ページから<code>navigator.serviceWorker.register(scriptURL, { scope })</code>を呼ぶと、ブラウザはワーカーのスクリプトと、制御対象を選ぶ<strong>scope</strong>を登録します。スクリプトURL、scope、登録を呼ぶページは同じoriginに属します。既定のscopeはスクリプトが置かれたディレクトリです。たとえば<code>/sample/offline/sw.js</code>なら<code>/sample/offline/</code>が既定です。サーバーが<code>Service-Worker-Allowed</code>ヘッダーで最大範囲を広げる方法もあります。<a href="https://developer.mozilla.org/en-US/docs/Web/API/ServiceWorkerContainer/register#parameters" target="_blank" rel="noreferrer">MDNのregister仕様とオプション</a></p><p>登録は<strong>secure context</strong>で行います。公開サイトのHTTPSが代表例です。ローカル開発では、ブラウザが信頼できるローカルoriginとして扱う<code>http://localhost</code>やループバックアドレスを利用できます。登録用のスクリプトとscopeにはHTTP(S) URLを使うため、教材のファイルもローカルのHTTPサーバーなどから配信します。<a href="https://w3c.github.io/webappsec-secure-contexts/#is-origin-trustworthy" target="_blank" rel="noreferrer">Secure Contextsの信頼できるorigin</a>、<a href="https://w3c.github.io/ServiceWorker/#start-register-algorithm" target="_blank" rel="noreferrer">Service Workersの登録手順</a></p><p>scopeは、主にどのページを担当するかを決めます。そのページがスクリプトや画像、API応答を求めると、取得先がページと別のパスにある要求も<code>fetch</code>イベントの対象になり得ます。どの要求を処理するかは、イベント内でmethod、URL、用途などを調べて選びます。<a href="https://w3c.github.io/ServiceWorker/#on-fetch-request-algorithm" target="_blank" rel="noreferrer">Service WorkersのHandle Fetch</a></p><h2 id="install、waiting、activate、ページの制御" tabindex="-1">install、waiting、activate、ページの制御 <a class="header-anchor" href="#install、waiting、activate、ページの制御" aria-label="Permalink to &quot;install、waiting、activate、ページの制御&quot;">​</a></h2><p>一つの登録には、新しい版を準備する<code>installing</code>、切り替えを待つ<code>waiting</code>、担当中または有効化中の<code>active</code>という枠があります。新しい版の準備中も、以前のactive workerが既存のページを担当できます。<a href="https://w3c.github.io/ServiceWorker/#service-worker-registration-concept" target="_blank" rel="noreferrer">Service Workersの登録モデル</a></p><table tabindex="0"><thead><tr><th>段階</th><th>起きること</th></tr></thead><tbody><tr><td><code>install</code></td><td>新しいワーカーが、先に必要な資源の保存などを行う</td></tr><tr><td><code>waiting</code></td><td>インストールを終え、新版をactiveにできる条件を待つ</td></tr><tr><td><code>activate</code></td><td>新版がactiveの枠へ移る。イベント内で移行や不要な保存物の整理を行える</td></tr></tbody></table><p><code>install</code>イベントでは、先に済ませる処理のPromiseを<code>event.waitUntil(...)</code>へ渡します。たとえば必須の画面資源を保存する処理を渡すと、ブラウザはその処理をインストールの一部として待ちます。Promiseが拒否された場合、その版のインストールは失敗します。途中で作ったCacheが残る場合もあるため、版ごとに保存先を分けます。<a href="https://developer.mozilla.org/en-US/docs/Web/API/ExtendableEvent/waitUntil" target="_blank" rel="noreferrer">MDNのwaitUntil</a>、<a href="https://w3c.github.io/ServiceWorker/#installation-algorithm" target="_blank" rel="noreferrer">Service WorkersのInstall手順</a></p><p>更新時は、旧版が担当するページが残っている間、新版はwaitingに留まることがあります。初回は旧版がいないため、待機が短く、その状態を観察しにくいこともあります。<code>activate</code>でも<code>waitUntil(...)</code>を使えます。そこで待つ処理がsettleして有効化が進むまで、通常の<code>fetch</code>などの処理は待たされます。<a href="https://w3c.github.io/ServiceWorker/#activation-algorithm" target="_blank" rel="noreferrer">Service WorkersのActivate手順</a>、<a href="https://developer.mozilla.org/en-US/docs/Web/API/ExtendableEvent/waitUntil" target="_blank" rel="noreferrer">MDNのwaitUntil</a></p><h3 id="readyとcontrollerが示す状態" tabindex="-1"><code>ready</code>と<code>controller</code>が示す状態 <a class="header-anchor" href="#readyとcontrollerが示す状態" aria-label="Permalink to &quot;`ready`と`controller`が示す状態&quot;">​</a></h3><table tabindex="0"><thead><tr><th>観察するもの</th><th>意味</th></tr></thead><tbody><tr><td><code>register()</code>のPromiseがfulfilled</td><td>登録オブジェクトが得られた</td></tr><tr><td><code>navigator.serviceWorker.ready</code>がfulfilled</td><td>現在のページに対応する登録にactive workerがある</td></tr><tr><td><code>navigator.serviceWorker.controller</code>がワーカーを返す</td><td>今のページはそのワーカーの制御下にある</td></tr></tbody></table><p>Service Workerの制御を受けずに開いたページで初回登録すると、通常は<code>ready</code>から登録を取得できても<code>controller</code>は<code>null</code>のままです。有効化後、scope内への通常の再読み込みや移動で新しく開いたページは、対応するactive workerの制御を受けます。ページを担当するワーカーが変わったことは<code>controllerchange</code>で観察できます。<a href="https://w3c.github.io/ServiceWorker/#navigator-service-worker-ready" target="_blank" rel="noreferrer">Service Workersのready</a>、<a href="https://w3c.github.io/ServiceWorker/#navigator-service-worker-controller" target="_blank" rel="noreferrer">Service Workersのcontroller</a>、<a href="https://web.dev/articles/service-worker-lifecycle#activate" target="_blank" rel="noreferrer">Chromeのライフサイクル解説</a></p><figure><img src="'+c+'" alt="Service Workerの登録からinstall、waiting、activateへ進む流れ、readyとcontrollerで観察する状態、次の読み込みでの制御開始、登録解除とCache削除を示す図" width="760" height="1510" loading="lazy"><figcaption>ワーカーを登録して準備する段階と、今のページがワーカーの担当になる段階を別々に観察できます。<a href="/study/images/browser/service-worker-lifecycle.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><h2 id="fetchイベントで応答を選ぶ" tabindex="-1">fetchイベントで応答を選ぶ <a class="header-anchor" href="#fetchイベントで応答を選ぶ" aria-label="Permalink to &quot;fetchイベントで応答を選ぶ&quot;">​</a></h2><p>ブラウザの取得処理がService Workerに要求を渡すと、ワーカーは<code>fetch</code>イベントの<code>event.request</code>から<code>Request</code>を読みます。対応する要求には<code>event.respondWith(...)</code>で<code>Response</code>、または<code>Response</code>が得られるPromiseを渡します。ハンドラーが応答を引き受けずに終了した場合は、HTTPキャッシュを含む通常の取得処理へ進めます。<a href="https://w3c.github.io/ServiceWorker/#fetch-event-respondwith" target="_blank" rel="noreferrer">Service WorkersのrespondWith</a>、<a href="https://fetch.spec.whatwg.org/#http-fetch" target="_blank" rel="noreferrer">WHATWG FetchのHTTP fetch</a></p><p><code>respondWith</code>を呼ぶのは、<strong>イベントが配送されている間</strong>です。Cache APIの検索や<code>fetch()</code>の完了を待つなら、その処理を行う関数が返すPromiseをハンドラーの同期部分で渡します。配送が終わってから<code>respondWith</code>を呼ぶと<code>InvalidStateError</code>になります。引き受けたPromiseが拒否された場合は取得の失敗となるので、代替応答が必要ならPromiseの処理に組み込みます。<a href="https://w3c.github.io/ServiceWorker/#dom-fetchevent-respondwith" target="_blank" rel="noreferrer">Service WorkersのrespondWith手順</a></p><h3 id="オフライン時に使う応答を用意する" tabindex="-1">オフライン時に使う応答を用意する <a class="header-anchor" href="#オフライン時に使う応答を用意する" aria-label="Permalink to &quot;オフライン時に使う応答を用意する&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方針</th><th>応答の選び方</th></tr></thead><tbody><tr><td>cache first</td><td>名前付きCacheにある応答を優先し、見つからなければ取得を試す</td></tr><tr><td>network first</td><td><code>fetch()</code>で通常の取得を試し、通信失敗など、アプリで決めた条件で保存済み応答に切り替える</td></tr><tr><td>合成応答</td><td><code>new Response(...)</code>で、その要求に対応する応答をワーカー内で作る</td></tr></tbody></table><p>Service Workerが自分で呼ぶ<code>fetch()</code>は、ワーカーによる介入を外した取得経路を使います。これにより、ハンドラー内の取得が同じService Workerの<code>fetch</code>イベントを再帰的に起こすことを防ぎます。<a href="https://fetch.spec.whatwg.org/#fetch-method" target="_blank" rel="noreferrer">WHATWG Fetchのfetchメソッド</a></p><p>ここでの<strong>fallback</strong>は、予定していた応答を得られない場合に返す代替応答です。たとえば、記事を開けないときはオフライン用HTMLを返し、データ取得が失敗したときは保存済みのデータを返せます。画像要求やAPI要求には、それぞれの呼び出し側が扱える形式を選びます。<code>fetch()</code>は<code>404</code>や<code>503</code>などのHTTP応答を受け取った場合もfulfilledになるため、通信失敗に加えてどのHTTP statusを切り替え条件にするかは、アプリで決めます。<a href="https://fetch.spec.whatwg.org/#fetch-method" target="_blank" rel="noreferrer">WHATWG Fetchのfetchメソッド</a></p><figure><img src="'+i+'" alt="固定GETのfetchイベントでrespondWithを呼び、通常の取得に失敗した場合や疑似オフライン時に専用Cacheを調べ、保存済み応答か503を返す実践の図" width="760" height="1510" loading="lazy"><figcaption>ワーカーが応答を引き受ける場合は、イベント内で<code>respondWith()</code>を呼びます。取得やキャッシュ検索を待つ処理は、渡すPromiseの中で進めます。<a href="/study/images/browser/service-worker-fetch.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><p>Cache APIの中身は、アプリが名前を付けて管理します。HTTPキャッシュの鮮度・再検証や、通常の<code>fetch()</code>がどこから応答を得たかは別の層です。オフラインで画面全体を開くなら、入口のHTMLと、その画面が使うCSS・JavaScript・画像などについて、事前に保存する範囲と欠けたときの動作を決めます。初回の取得に失敗した場合や、保存領域が削除された場合にも、手元に応答があるかどうかで表示は変わります。<a href="https://w3c.github.io/ServiceWorker/#cache-lifetimes" target="_blank" rel="noreferrer">Service WorkersのCacheの寿命</a>、<a href="/study/network/http-caching.html">HTTPキャッシュ</a>、<a href="/study/browser/storage-lifetime.html">ブラウザの保存領域</a></p><p><code>navigator.onLine</code>はブラウザが判断する接続状態の目安です。ネットワークにつながっていても、目的のサーバーへ到達できるかはDNSや経路、サーバーの状態にもよります。接続状態は表示の手がかりに使い、要求ごとの成功・失敗は取得結果から判断します。<a href="https://html.spec.whatwg.org/multipage/system-state.html#browser-state" target="_blank" rel="noreferrer">WHATWG HTMLの接続状態</a></p><h2 id="更新時はページとワーカーとcacheの版をそろえる" tabindex="-1">更新時はページとワーカーとCacheの版をそろえる <a class="header-anchor" href="#更新時はページとワーカーとcacheの版をそろえる" aria-label="Permalink to &quot;更新時はページとワーカーとCacheの版をそろえる&quot;">​</a></h2><p>ブラウザは更新チェックで、取得したワーカーのスクリプト資源を以前のバイト列と比較します。<code>updateViaCache</code>は、このチェックで本体やimport先をHTTPキャッシュから取得する方針に関わる設定です。アプリがCache APIへ保存した応答は、アプリ側で版と更新手順を管理します。<a href="https://w3c.github.io/ServiceWorker/#update-algorithm" target="_blank" rel="noreferrer">Service WorkersのUpdate手順</a></p><p>スクリプトが更新されると、ブラウザは新版をインストールし、切り替えの条件が整うまで待機させます。たとえば旧版のページが遅れて追加のJavaScriptを要求するときに、旧版のファイルを先に消すと、そのページの操作が失敗します。新版の資源は<code>app-static-v2</code>のような版付きCacheに準備し、旧版の利用が終わったことを考慮して、担当アプリの旧Cacheだけを整理します。<a href="https://web.dev/articles/service-worker-lifecycle#updating-the-service-worker" target="_blank" rel="noreferrer">ChromeのService Worker更新解説</a>、<a href="https://w3c.github.io/ServiceWorker/#cache-lifetimes" target="_blank" rel="noreferrer">Service WorkersのCacheの寿命</a></p><p><code>skipWaiting()</code>は、新版がインストールを済ませた後、旧版を使うページが開いていても有効化を進めるための操作です。<code>clients.claim()</code>は、active workerが条件に合う既存ページのcontrollerになれるようにします。切り替え後も、開いたページでは読み込み済みのJavaScriptやCSSを使い続けます。すぐに切り替える場合は、旧ページと新版が一時的に組み合わさる間の互換性や、ページを再読み込みする時点を考えます。<a href="https://web.dev/articles/service-worker-lifecycle#skip_the_waiting_phase" target="_blank" rel="noreferrer">ChromeのskipWaiting解説</a>、<a href="https://developer.mozilla.org/en-US/docs/Web/API/Clients/claim" target="_blank" rel="noreferrer">MDNのclients.claim</a></p><h2 id="登録解除と保存物の削除" tabindex="-1">登録解除と保存物の削除 <a class="header-anchor" href="#登録解除と保存物の削除" aria-label="Permalink to &quot;登録解除と保存物の削除&quot;">​</a></h2><p><code>registration.unregister()</code>は、そのscopeの登録を解除する操作です。解除後も、すでに制御されているページは、閉じるか次のナビゲーションに進むまで旧ワーカーの制御を受け続ける場合があります。解除のPromise、現在の<code>controller</code>、次に開いたページの制御状態をそれぞれ観察できます。<a href="https://w3c.github.io/ServiceWorker/#navigator-service-worker-unregister" target="_blank" rel="noreferrer">Service Workersのunregister</a></p><p>名前付きCacheの削除には別に<code>caches.delete(name)</code>などを使います。登録とCacheは寿命が異なるため、解除後も保存した応答をページから確認できます。名前付きCacheの一覧には、同じ保存領域を使う別アプリのものも含まれます。後片付けで指定するのは、当該アプリが所有するCache名です。<a href="https://w3c.github.io/ServiceWorker/#cache-lifetimes" target="_blank" rel="noreferrer">Service WorkersのCacheの寿命</a></p><h2 id="実践との対応" tabindex="-1">実践との対応 <a class="header-anchor" href="#実践との対応" aria-label="Permalink to &quot;実践との対応&quot;">​</a></h2><p>実践では教材専用ディレクトリをscopeにし、登録と再読み込みの前後でcontrollerを観察します。ワーカーは<code>payload.json</code>のGETで通常の取得を試し、失敗時にはinstallで専用Cacheに保存した応答を返します。<code>?mode=offline</code>は対象の要求だけ通常の取得を省略する、教材用の疑似オフライン分岐です。HTMLやCSS、JavaScriptは通常の配信から読み込みます。登録解除後は再読み込みでcontrollerを確認し、専用Cacheの対象応答を別の操作で削除します。<a href="/study/practice/browser/service-worker-observation.html">Service Workerの登録と応答を観察する</a></p>',35)])])}const v=r(s,[["render",l]]);export{k as __pageData,v as default};
